/**
 * Ready-made demo project for first-time visitors.
 *
 * The storyboard is generated by the normal template engine from a short
 * story (nothing is hardcoded in the engine). Six original sample
 * illustrations from /demo/ are then stored in this browser's media storage
 * and attached one per scene, so the Video maker can play and export at once.
 */
import { generateStoryboard } from './storyEngine.js';
import { DEMO_CHARACTERS } from './demoPresets.js';
import { defaultSceneMedia, defaultVideoSettings } from './video/videoModel.js';

export const DEMO_SETTINGS = {
  title: 'The Letter That Remembered (demo project)',
  genre: 'mystery',
  style: 'cinematic',
  language: 'English',
  sceneCount: 6,
  duration: 30,
  aspectRatio: '9:16',
  includeAudio: true,
  characterDescription: DEMO_CHARACTERS,
  story: [
    "On a rain-soaked night, a sealed envelope with no return address slides under Elena's door.",
    'Inside, a faded letter reads: "Come to Ravenscourt before midnight. The truth is waiting."',
    'Elena reaches the iron gates of the abandoned mansion as lightning splits the sky.',
    "In the dusty foyer, a portrait on the stairs shows a woman wearing Elena's silver crescent pendant.",
    'A tall stranger steps out of the shadows and says, "You look just like her."',
    'The front door slams behind her, and every candle in the hall goes out.',
  ].join('\n'),
};

export const DEMO_IMAGES = Array.from({ length: 6 }, (_, i) => ({
  url: `/demo/scene-${i + 1}.webp`,
  name: `StoryMotion demo image ${i + 1}.webp`,
}));

export function buildDemoBoard() {
  return generateStoryboard(DEMO_SETTINGS);
}

/**
 * Downloads the sample images, stores them locally via `importImage`, and
 * returns a copy of the board with video settings that use them.
 * Never throws: failed images are skipped and counted.
 */
export async function attachDemoImages(board, { importImage, fetchImpl = globalThis.fetch, signal } = {}) {
  const video = defaultVideoSettings();
  let failed = 0;
  const results = await Promise.all(
    board.scenes.map(async (scene, i) => {
      const img = DEMO_IMAGES[i];
      if (!img) return null;
      try {
        const res = await fetchImpl(img.url, { signal, cache: 'force-cache' });
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const blob = await res.blob();
        const stored = await importImage(blob, { name: img.name, source: 'upload' });
        return { sceneId: scene.id, stored };
      } catch (err) {
        if (signal?.aborted) throw err;
        failed += 1;
        return null;
      }
    }),
  );
  for (const r of results) {
    if (!r) continue;
    video.scenes[r.sceneId] = {
      ...defaultSceneMedia(),
      imageId: r.stored.id,
      imageName: r.stored.name,
      imageSource: 'upload',
      imageWidth: r.stored.width,
      imageHeight: r.stored.height,
    };
  }
  const attached = results.filter(Boolean).length;
  return { board: { ...board, video }, attached, failed };
}
